export default function BashkirMemoryPalace() {
  const [tab, setTab] = useState('palace');
  const [lang, setLang] = useState('en');
  const [station, setStation] = useState(null);
  const [artifacts, setArtifacts] = useState([]);
  const [visited, setVisited] = useState([]);
  const [showTreasure, setShowTreasure] = useState(false);
  const [wordStrengths, setWordStrengths] = useState({});
  const [quizWord, setQuizWord] = useState(null);
  const [showAnswer, setShowAnswer] = useState(false);
  const [quizMode, setQuizMode] = useState('ba-en');
  const [grammarTopic, setGrammarTopic] = useState(0);
  const [vocabSearch, setVocabSearch] = useState('');
  const [vocabFilter, setVocabFilter] = useState('all');
  const [glueCategory, setGlueCategory] = useState('pronouns');
  const [patternIndex, setPatternIndex] = useState(0);

  const t = (en, ba) => lang === 'en' ? en : ba;
  const enterStation = (id) => { setStation(id); if (!visited.includes(id)) setVisited([...visited, id]); };
  const collectArtifact = (id) => { if (!artifacts.includes(id)) setArtifacts([...artifacts, id]); };
  const getStationVocab = (stationId) => allVocabulary.filter(v => v.station === stationId);
  
  const filteredVocab = useMemo(() => {
    let filtered = allVocabulary;
    if (vocabSearch) {
      const search = vocabSearch.toLowerCase();
      filtered = filtered.filter(v => v.ba.toLowerCase().includes(search) || v.en.toLowerCase().includes(search));
    }
    if (vocabFilter !== 'all') {
      filtered = filtered.filter(v => v.category === vocabFilter);
    }
    return filtered;
  }, [vocabSearch, vocabFilter]);

  const categories = [...new Set(allVocabulary.map(v => v.category))].sort();

  const rateWord = (wordId, rating) => {
    setWordStrengths(prev => ({ ...prev, [wordId]: rating }));
    nextQuizWord();
  };

  const nextQuizWord = () => {
    const weakWords = allVocabulary.filter(v => !wordStrengths[v.id] || wordStrengths[v.id] < 4);
    const pool = weakWords.length > 0 ? weakWords : allVocabulary;
    setQuizWord(pool[Math.floor(Math.random() * pool.length)]);
    setShowAnswer(false);
  };

  const getStrengthColor = (wordId) => strengthColors[(wordStrengths[wordId] || 1) - 1];
  const masteredCount = Object.values(wordStrengths).filter(s => s >= 4).length;
  const totalWords = allVocabulary.length;

  // ════════════════════════════════════════════════════════════
  // PALACE TAB
  // ════════════════════════════════════════════════════════════
  const renderPalace = () => {
    if (station === null) {
      return (
        <div style={{ padding: '12px' }}>
          <div style={{ backgroundColor: colors.darkBlue, padding: '12px', borderRadius: '8px', textAlign: 'center', marginBottom: '16px' }}>
            <span style={{ color: colors.honey, fontSize: '24px' }}>⬡</span>
            <span style={{ color: colors.white, marginLeft: '8px' }}>{artifacts.length}/13 artifacts • {totalWords} words</span>
            {artifacts.length === 13 && (
              <button onClick={() => setShowTreasure(true)} style={{ marginLeft: '12px', backgroundColor: colors.gold, color: colors.darkBlue, padding: '4px 12px', borderRadius: '20px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}>🎁</button>
            )}
          </div>

          <h3 style={{ backgroundColor: colors.green, color: colors.white, padding: '8px', borderRadius: '4px', fontSize: '14px', marginBottom: '8px' }}>PART I: Urban — Өфө</h3>
          {stations.filter(s => s.part === 'urban').map(s => (
            <button key={s.id} onClick={() => enterStation(s.id)}
              style={{ width: '100%', padding: '10px', marginBottom: '6px', borderRadius: '6px', border: artifacts.includes(s.id) ? `2px solid ${colors.honey}` : '2px solid transparent',
                backgroundColor: visited.includes(s.id) ? colors.green : colors.white, color: visited.includes(s.id) ? colors.white : colors.blue,
                display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer', textAlign: 'left' }}>
              <span><span style={{ fontSize: '16px', marginRight: '8px' }}>{s.emoji}</span><strong>{s.id}. {t(s.nameEn, s.nameBa)}</strong></span>
              {artifacts.includes(s.id) && <span style={{ color: colors.honey }}>⬡</span>}
            </button>
          ))}

          <h3 style={{ backgroundColor: colors.earth, color: colors.white, padding: '8px', borderRadius: '4px', fontSize: '14px', marginBottom: '8px', marginTop: '12px' }}>PART II: Rural — Ауыл</h3>
          {stations.filter(s => s.part === 'rural').map(s => (
            <button key={s.id} onClick={() => enterStation(s.id)}
              style={{ width: '100%', padding: '10px', marginBottom: '6px', borderRadius: '6px', border: artifacts.includes(s.id) ? `2px solid ${colors.honey}` : '2px solid transparent',
                backgroundColor: visited.includes(s.id) ? colors.earth : colors.cream, color: visited.includes(s.id) ? colors.white : colors.earth,
                display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer', textAlign: 'left' }}>
              <span><span style={{ fontSize: '16px', marginRight: '8px' }}>{s.emoji}</span><strong>{s.id}. {t(s.nameEn, s.nameBa)}</strong></span>
              {artifacts.includes(s.id) && <span style={{ color: colors.honey }}>⬡</span>}
            </button>
          ))}
        </div>
      );
    }

    const s = stations.find(st => st.id === station);
    const vocab = getStationVocab(station);
    const isRural = s.part === 'rural';
    const headerBg = isRural ? colors.earth : colors.blue;

    return (
      <div>
        <div style={{ backgroundColor: headerBg, padding: '10px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
            <button onClick={() => setStation(null)} style={{ backgroundColor: colors.white, color: headerBg, padding: '4px 10px', borderRadius: '4px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}>← Map</button>
            <div style={{ display: 'flex', gap: '4px' }}>
              {s.id > 0 && <button onClick={() => enterStation(s.id - 1)} style={{ backgroundColor: 'rgba(255,255,255,0.3)', color: colors.white, padding: '4px 8px', borderRadius: '4px', border: 'none', cursor: 'pointer' }}>←</button>}
              {s.id < 12 && <button onClick={() => enterStation(s.id + 1)} style={{ backgroundColor: 'rgba(255,255,255,0.3)', color: colors.white, padding: '4px 8px', borderRadius: '4px', border: 'none', cursor: 'pointer' }}>→</button>}
            </div>
          </div>
          <div style={{ textAlign: 'center' }}>
            <span style={{ fontSize: '28px' }}>{s.emoji}</span>
            <h2 style={{ color: colors.white, fontSize: '16px', margin: '4px 0' }}>{s.id}. {t(s.nameEn, s.nameBa)}</h2>
          </div>
        </div>

        <div style={{ backgroundImage: `url(${stationImages[s.id]})`, backgroundSize: s.id === 0 ? 'contain' : 'cover', backgroundRepeat: 'no-repeat', backgroundColor: s.id === 0 ? '#1a1a2e' : 'transparent', backgroundPosition: imagePositions[s.id], height: '140px' }} />

        <div style={{ backgroundColor: isRural ? colors.earth : colors.blue, padding: '10px' }}>
          <div style={{ backgroundColor: 'rgba(255,255,255,0.1)', borderRadius: '6px', padding: '10px', marginBottom: '10px' }}>
            <p style={{ color: colors.white, fontSize: '13px', margin: 0 }}>{s.descEn}</p>
          </div>

          <div style={{ backgroundColor: 'rgba(212,175,55,0.2)', borderRadius: '6px', padding: '10px', marginBottom: '10px', borderLeft: `3px solid ${colors.gold}` }}>
            <p style={{ color: colors.gold, fontSize: '11px', fontWeight: 'bold', margin: '0 0 4px' }}>🧠 METHOD OF LOCI</p>
            <p style={{ color: colors.white, fontSize: '14px', margin: 0, fontStyle: 'italic', lineHeight: '1.4' }}>{s.lociHint}</p>
          </div>

          <div style={{ backgroundColor: 'rgba(255,255,255,0.95)', borderRadius: '6px', overflow: 'hidden', marginBottom: '10px' }}>
            <div style={{ backgroundColor: colors.green, padding: '8px', fontWeight: 'bold', fontSize: '13px', color: colors.white }}>📚 Vocabulary ({vocab.length})</div>
            <div style={{ padding: '6px', maxHeight: '180px', overflowY: 'auto' }}>
              {vocab.map(w => (
                <div key={w.id} style={{ backgroundColor: colors.cream, borderRadius: '4px', padding: '6px', marginBottom: '4px', borderLeft: `3px solid ${getStrengthColor(w.id)}` }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <strong style={{ color: colors.blue, fontSize: '18px' }}>{w.ba}</strong>
                    <span style={{ color: colors.darkBlue, fontSize: '15px' }}>{w.en}</span>
                  </div>
                  <div style={{ color: '#666', fontSize: '12px', marginTop: '4px' }}>💡 {w.mnemonic}</div>
                  <div style={{ color: colors.darkBlue, fontSize: '13px', marginTop: '4px', fontStyle: 'italic' }}>{w.sentence}</div>
                </div>
              ))}
            </div>
          </div>

          {!artifacts.includes(s.id) ? (
            <button onClick={() => collectArtifact(s.id)} style={{ width: '100%', padding: '12px', backgroundColor: colors.honey, color: colors.darkBlue, border: 'none', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer' }}>⬡ COLLECT ARTIFACT</button>
          ) : (
            <div style={{ backgroundColor: `${colors.honey}30`, border: `2px solid ${colors.honey}`, borderRadius: '6px', padding: '10px' }}>
              <span style={{ color: colors.honey }}>⬡</span> <strong style={{ color: colors.honey }}>{t(s.artifact.nameEn, s.artifact.nameBa)}</strong>
              <p style={{ color: colors.white, fontSize: '12px', margin: '4px 0 0' }}>{s.artifact.text}</p>
            </div>
          )}
        </div>
      </div>
    );
  };

  // ════════════════════════════════════════════════════════════
  // GRAMMAR TAB
  // ════════════════════════════════════════════════════════════
  const renderGrammar = () => (
    <div style={{ padding: '12px' }}>
      <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap', marginBottom: '12px' }}>
        {grammarTopics.map((topic, i) => (
          <button key={i} onClick={() => setGrammarTopic(i)}
            style={{ padding: '5px 8px', backgroundColor: grammarTopic === i ? colors.honey : colors.darkBlue, color: grammarTopic === i ? colors.darkBlue : colors.white, border: 'none', borderRadius: '4px', fontSize: '10px', cursor: 'pointer' }}>
            {topic.title.split(' ')[0]}
          </button>
        ))}
      </div>
      <div style={{ backgroundColor: colors.cream, borderRadius: '8px', padding: '12px' }}>
        <h3 style={{ color: colors.blue, margin: '0 0 4px', fontSize: '16px' }}>{grammarTopics[grammarTopic].title}</h3>
        <p style={{ color: colors.green, margin: '0 0 10px', fontSize: '12px' }}>{grammarTopics[grammarTopic].titleBa}</p>
        <div style={{ color: colors.darkBlue, fontSize: '14px', whiteSpace: 'pre-wrap', lineHeight: '1.6' }}>
          {grammarTopics[grammarTopic].content.split('\n').map((line, i) => {
            if (line.startsWith('**') && line.endsWith('**')) return <p key={i} style={{ fontWeight: 'bold', margin: '8px 0 4px' }}>{line.replace(/\*\*/g, '')}</p>;
            if (line.startsWith('|')) return <pre key={i} style={{ fontSize: '10px', overflow: 'auto', margin: '2px 0' }}>{line}</pre>;
            if (line.startsWith('•')) return <p key={i} style={{ margin: '2px 0', paddingLeft: '10px' }}>{line}</p>;
            return <p key={i} style={{ margin: '4px 0' }}>{line.replace(/\*\*/g, '')}</p>;
          })}
        </div>
      </div>
    </div>
  );

  // ════════════════════════════════════════════════════════════
  // WORDS & SENTENCES TAB
  // ════════════════════════════════════════════════════════════
  const renderWords = () => (
    <div style={{ padding: '12px' }}>
      {/* Sub-tabs */}
      <div style={{ display: 'flex', gap: '4px', marginBottom: '12px' }}>
        {['vocabulary', 'glue', 'sentences'].map(sub => (
          <button key={sub} onClick={() => setVocabFilter(sub === 'vocabulary' ? 'all' : sub)}
            style={{ flex: 1, padding: '8px', backgroundColor: (vocabFilter === 'all' && sub === 'vocabulary') || vocabFilter === sub ? colors.honey : colors.darkBlue,
              color: (vocabFilter === 'all' && sub === 'vocabulary') || vocabFilter === sub ? colors.darkBlue : colors.white, border: 'none', borderRadius: '4px', fontWeight: 'bold', fontSize: '11px', cursor: 'pointer' }}>
            {sub === 'vocabulary' ? '📚 All Words' : sub === 'glue' ? '🔗 Glue Words' : '✍️ Sentences'}
          </button>
        ))}
      </div>

      {/* Vocabulary Browser */}
      {vocabFilter !== 'glue' && vocabFilter !== 'sentences' && (
        <>
          <input type="text" placeholder="Search words..." value={vocabSearch} onChange={e => setVocabSearch(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: `1px solid ${colors.blue}`, marginBottom: '8px', boxSizing: 'border-box' }} />
          <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap', marginBottom: '8px' }}>
            <button onClick={() => setVocabFilter('all')} style={{ padding: '4px 8px', backgroundColor: vocabFilter === 'all' ? colors.green : colors.cream, color: vocabFilter === 'all' ? colors.white : colors.darkBlue, border: 'none', borderRadius: '4px', fontSize: '10px', cursor: 'pointer' }}>All</button>
            {categories.map(cat => (
              <button key={cat} onClick={() => setVocabFilter(cat)} style={{ padding: '4px 8px', backgroundColor: vocabFilter === cat ? colors.green : colors.cream, color: vocabFilter === cat ? colors.white : colors.darkBlue, border: 'none', borderRadius: '4px', fontSize: '10px', cursor: 'pointer' }}>{cat}</button>
            ))}
          </div>
          <p style={{ color: colors.white, fontSize: '11px', marginBottom: '8px' }}>{filteredVocab.length} words</p>
          <div style={{ maxHeight: '400px', overflowY: 'auto' }}>
            {filteredVocab.map(w => (
              <div key={w.id} style={{ backgroundColor: colors.cream, borderRadius: '6px', padding: '12px', marginBottom: '8px', borderLeft: `4px solid ${getStrengthColor(w.id)}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <strong style={{ color: colors.blue, fontSize: '20px' }}>{w.ba}</strong>
                  <span style={{ color: colors.darkBlue, fontSize: '16px' }}>{w.en}</span>
                </div>
                <div style={{ color: colors.green, fontSize: '13px' }}>{w.ipa} • "{w.approx}"</div>
                <div style={{ color: '#666', fontSize: '12px', marginTop: '4px' }}>💡 {w.mnemonic}</div>
                {w.cognate && <div style={{ color: '#888', fontSize: '12px' }}>🔗 {w.cognate}</div>}
                <div style={{ color: colors.darkBlue, fontSize: '14px', marginTop: '6px', fontStyle: 'italic', backgroundColor: 'rgba(0,0,0,0.05)', padding: '6px', borderRadius: '3px' }}>{w.sentence}</div>
              </div>
            ))}
          </div>
        </>
      )}

      {/* Glue Words */}
      {vocabFilter === 'glue' && (
        <>
          <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap', marginBottom: '12px' }}>
            {Object.keys(glueWords).map(cat => (
              <button key={cat} onClick={() => setGlueCategory(cat)}
                style={{ padding: '6px 10px', backgroundColor: glueCategory === cat ? colors.honey : colors.darkBlue, color: glueCategory === cat ? colors.darkBlue : colors.white, border: 'none', borderRadius: '4px', fontSize: '10px', cursor: 'pointer' }}>
                {cat === 'pronouns' ? '👤 Pronouns' : cat === 'postpositions' ? '📍 Postpositions' : cat === 'conjunctions' ? '🔗 Conjunctions' : cat === 'questionWords' ? '❓ Questions' : cat === 'numbers' ? '🔢 Numbers' : '✨ Particles'}
              </button>
            ))}
          </div>
          <div style={{ backgroundColor: colors.cream, borderRadius: '8px', padding: '12px', maxHeight: '400px', overflowY: 'auto' }}>
            {glueCategory === 'postpositions' && (
              <p style={{ color: colors.blue, fontSize: '11px', marginBottom: '10px', fontStyle: 'italic' }}>⚠️ Bashkir uses POSTPOSITIONS (come AFTER the noun), not prepositions!</p>
            )}
            {glueWords[glueCategory].map((item, i) => (
              <div key={i} style={{ backgroundColor: colors.white, borderRadius: '4px', padding: '8px', marginBottom: '6px', borderLeft: `3px solid ${colors.green}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <strong style={{ color: colors.blue, fontSize: '20px' }}>{item.ba}</strong>
                  <span style={{ color: colors.darkBlue, fontSize: '16px' }}>{item.en}</span>
                </div>
                {item.ipa && <div style={{ color: colors.green, fontSize: '13px' }}>{item.ipa}</div>}
                {item.note && <div style={{ color: '#666', fontSize: '13px', marginTop: '4px' }}>{item.note}</div>}
                {item.example && <div style={{ color: colors.darkBlue, fontSize: '14px', marginTop: '6px', fontStyle: 'italic' }}>→ {item.example}</div>}
              </div>
            ))}
          </div>
        </>
      )}

      {/* Sentence Patterns */}
      {vocabFilter === 'sentences' && (
        <>
          <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap', marginBottom: '12px' }}>
            {sentencePatterns.map((p, i) => (
              <button key={i} onClick={() => setPatternIndex(i)}
                style={{ padding: '4px 8px', backgroundColor: patternIndex === i ? colors.honey : colors.darkBlue, color: patternIndex === i ? colors.darkBlue : colors.white, border: 'none', borderRadius: '4px', fontSize: '9px', cursor: 'pointer' }}>
                {p.pattern.split(' ')[0]}
              </button>
            ))}
          </div>
          <div style={{ backgroundColor: colors.cream, borderRadius: '8px', padding: '12px' }}>
            <h3 style={{ color: colors.blue, margin: '0 0 4px', fontSize: '14px' }}>{sentencePatterns[patternIndex].pattern}</h3>
            <p style={{ color: colors.green, fontSize: '12px', margin: '0 0 12px', fontFamily: 'monospace' }}>{sentencePatterns[patternIndex].formula}</p>
            {sentencePatterns[patternIndex].examples.map((ex, i) => (
              <div key={i} style={{ backgroundColor: colors.white, borderRadius: '4px', padding: '8px', marginBottom: '8px' }}>
                <p style={{ color: colors.blue, fontSize: '18px', fontWeight: 'bold', margin: '0 0 6px' }}>{ex.ba}</p>
                <p style={{ color: colors.darkBlue, fontSize: '15px', margin: '0 0 6px' }}>{ex.en}</p>
                <p style={{ color: '#666', fontSize: '12px', margin: 0 }}>📝 {ex.breakdown}</p>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );

  // ════════════════════════════════════════════════════════════
  // QUIZ TAB
  // ════════════════════════════════════════════════════════════
  const renderQuiz = () => {
    if (!quizWord) {
      return (
        <div style={{ padding: '16px', textAlign: 'center' }}>
          <h2 style={{ color: colors.white, marginBottom: '16px' }}>🎯 Flashcard Quiz</h2>
          <p style={{ color: colors.white, marginBottom: '16px' }}>Test your memory! Rate each word honestly.</p>
          <div style={{ display: 'flex', gap: '8px', justifyContent: 'center', marginBottom: '16px' }}>
            <button onClick={() => setQuizMode('ba-en')} style={{ padding: '8px 16px', backgroundColor: quizMode === 'ba-en' ? colors.honey : colors.darkBlue, color: quizMode === 'ba-en' ? colors.darkBlue : colors.white, border: 'none', borderRadius: '4px', cursor: 'pointer' }}>БШҚ → ENG</button>
            <button onClick={() => setQuizMode('en-ba')} style={{ padding: '8px 16px', backgroundColor: quizMode === 'en-ba' ? colors.honey : colors.darkBlue, color: quizMode === 'en-ba' ? colors.darkBlue : colors.white, border: 'none', borderRadius: '4px', cursor: 'pointer' }}>ENG → БШҚ</button>
          </div>
          <button onClick={nextQuizWord} style={{ padding: '16px 32px', backgroundColor: colors.green, color: colors.white, border: 'none', borderRadius: '8px', fontSize: '18px', fontWeight: 'bold', cursor: 'pointer' }}>Start Quiz</button>
        </div>
      );
    }

    return (
      <div style={{ padding: '16px' }}>
        <div style={{ textAlign: 'center', marginBottom: '12px' }}>
          <span style={{ color: colors.white, fontSize: '12px' }}>Mastered: {masteredCount}/{totalWords} ({Math.round(masteredCount/totalWords*100)}%)</span>
        </div>
        <div style={{ backgroundColor: colors.darkBlue, borderRadius: '12px', padding: '24px', textAlign: 'center', marginBottom: '16px' }}>
          <p style={{ color: colors.white, fontSize: '12px', margin: '0 0 8px' }}>{quizMode === 'ba-en' ? 'What does this mean?' : 'How do you say...'}</p>
          <p style={{ color: colors.honey, fontSize: '36px', fontWeight: 'bold', margin: '0 0 8px' }}>{quizMode === 'ba-en' ? quizWord.ba : quizWord.en}</p>
          {quizMode === 'ba-en' && <p style={{ color: colors.white, fontSize: '12px', margin: 0, opacity: 0.7 }}>{quizWord.ipa}</p>}
        </div>

        {!showAnswer ? (
          <button onClick={() => setShowAnswer(true)} style={{ width: '100%', padding: '16px', backgroundColor: colors.green, color: colors.white, border: 'none', borderRadius: '8px', fontSize: '16px', fontWeight: 'bold', cursor: 'pointer', marginBottom: '16px' }}>Show Answer</button>
        ) : (
          <div>
            <div style={{ backgroundColor: colors.cream, borderRadius: '8px', padding: '16px', marginBottom: '16px' }}>
              <p style={{ color: colors.blue, fontSize: '32px', fontWeight: 'bold', margin: '0 0 10px', textAlign: 'center' }}>{quizMode === 'ba-en' ? quizWord.en : quizWord.ba}</p>
              <p style={{ color: '#666', fontSize: '14px', margin: '0 0 10px', textAlign: 'center' }}>💡 {quizWord.mnemonic}</p>
              <p style={{ color: colors.darkBlue, fontSize: '15px', margin: 0, textAlign: 'center', fontStyle: 'italic' }}>{quizWord.sentence}</p>
            </div>
            <p style={{ color: colors.white, fontSize: '12px', textAlign: 'center', marginBottom: '8px' }}>How well did you know it?</p>
            <div style={{ display: 'flex', gap: '6px', justifyContent: 'center' }}>
              {[1,2,3,4,5].map(r => (
                <button key={r} onClick={() => rateWord(quizWord.id, r)} style={{ width: '50px', height: '50px', backgroundColor: strengthColors[r-1], color: r < 3 ? colors.white : colors.darkBlue, border: 'none', borderRadius: '8px', fontSize: '18px', fontWeight: 'bold', cursor: 'pointer' }}>{r}</button>
              ))}
            </div>
            <div style={{ display: 'flex', gap: '6px', justifyContent: 'center', marginTop: '4px' }}>
              {strengthLabels.map((l, i) => <span key={i} style={{ width: '50px', fontSize: '9px', color: colors.white, textAlign: 'center' }}>{l}</span>)}
            </div>
          </div>
        )}
        <button onClick={() => { setQuizWord(null); setShowAnswer(false); }} style={{ width: '100%', marginTop: '16px', padding: '10px', backgroundColor: 'transparent', color: colors.white, border: `1px solid ${colors.white}`, borderRadius: '6px', cursor: 'pointer' }}>End Quiz</button>
      </div>
    );
  };

  // ════════════════════════════════════════════════════════════
  // PROGRESS TAB
  // ════════════════════════════════════════════════════════════
  const renderProgress = () => {
    const stationProgress = stations.map(s => {
      const vocab = getStationVocab(s.id);
      const mastered = vocab.filter(v => wordStrengths[v.id] >= 4).length;
      return { ...s, total: vocab.length, mastered };
    });

    return (
      <div style={{ padding: '12px' }}>
        <div style={{ backgroundColor: colors.darkBlue, borderRadius: '8px', padding: '16px', marginBottom: '16px', textAlign: 'center' }}>
          <p style={{ color: colors.white, margin: '0 0 8px' }}>Overall Mastery</p>
          <p style={{ color: colors.honey, fontSize: '36px', fontWeight: 'bold', margin: '0 0 8px' }}>{Math.round(masteredCount/totalWords*100)}%</p>
          <p style={{ color: colors.white, margin: 0, fontSize: '12px' }}>{masteredCount} of {totalWords} words mastered</p>
          <div style={{ marginTop: '12px', height: '8px', backgroundColor: 'rgba(255,255,255,0.2)', borderRadius: '4px', overflow: 'hidden' }}>
            <div style={{ height: '100%', width: `${masteredCount/totalWords*100}%`, backgroundColor: colors.lime }} />
          </div>
        </div>

        <h3 style={{ color: colors.white, fontSize: '14px', marginBottom: '8px' }}>By Station</h3>
        {stationProgress.map(s => (
          <div key={s.id} style={{ backgroundColor: 'rgba(255,255,255,0.1)', borderRadius: '6px', padding: '8px', marginBottom: '4px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
              <span style={{ color: colors.white, fontSize: '12px' }}>{s.emoji} {s.nameEn}</span>
              <span style={{ color: colors.honey, fontSize: '11px' }}>{s.mastered}/{s.total}</span>
            </div>
            <div style={{ height: '4px', backgroundColor: 'rgba(255,255,255,0.2)', borderRadius: '2px', overflow: 'hidden' }}>
              <div style={{ height: '100%', width: `${s.total > 0 ? s.mastered/s.total*100 : 0}%`, backgroundColor: colors.lime }} />
            </div>
          </div>
        ))}

        <div style={{ marginTop: '16px', display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {strengthLabels.map((l, i) => (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <div style={{ width: '14px', height: '14px', backgroundColor: strengthColors[i], borderRadius: '3px' }} />
              <span style={{ color: colors.white, fontSize: '10px' }}>{l}</span>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ════════════════════════════════════════════════════════════
  // MAIN RENDER
  // ════════════════════════════════════════════════════════════
  return (
    <div style={{ minHeight: '100vh', backgroundColor: colors.blue }}>
      <div style={{ backgroundColor: colors.darkBlue, padding: '10px 12px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h1 style={{ color: colors.white, fontSize: '15px', fontWeight: 'bold', margin: 0 }}>🏛️ Bashkir Memory Palace</h1>
        <button onClick={() => setLang(l => l === 'en' ? 'ba' : 'en')} style={{ backgroundColor: colors.honey, color: colors.darkBlue, padding: '4px 10px', borderRadius: '12px', border: 'none', fontSize: '10px', fontWeight: 'bold', cursor: 'pointer' }}>{lang === 'en' ? 'БШҚ' : 'ENG'}</button>
      </div>

      <div style={{ display: 'flex', backgroundColor: colors.darkBlue }}>
        {[
          { id: 'palace', label: '🏛️', full: 'Palace' },
          { id: 'grammar', label: '📖', full: 'Grammar' },
          { id: 'words', label: '📚', full: 'Words' },
          { id: 'quiz', label: '🎯', full: 'Quiz' },
          { id: 'progress', label: '📊', full: 'Progress' }
        ].map(t => (
          <button key={t.id} onClick={() => { setTab(t.id); setStation(null); }}
            style={{ flex: 1, padding: '8px 2px', backgroundColor: tab === t.id ? colors.blue : 'transparent', color: colors.white, border: 'none', fontSize: '10px', cursor: 'pointer', borderBottom: tab === t.id ? `2px solid ${colors.honey}` : '2px solid transparent' }}>
            {t.label}<br/><span style={{ fontSize: '8px' }}>{t.full}</span>
          </button>
        ))}
      </div>

      <div style={{ paddingBottom: '20px' }}>
        {tab === 'palace' && renderPalace()}
        {tab === 'grammar' && renderGrammar()}
        {tab === 'words' && renderWords()}
        {tab === 'quiz' && renderQuiz()}
        {tab === 'progress' && renderProgress()}
      </div>

      {showTreasure && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.9)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '16px', zIndex: 50 }}>
          <div style={{ backgroundColor: colors.darkBlue, borderRadius: '12px', maxWidth: '360px', width: '100%', overflow: 'hidden' }}>
            <div style={{ backgroundColor: colors.gold, padding: '16px', textAlign: 'center' }}>
              <h2 style={{ margin: 0, color: colors.darkBlue, fontSize: '20px' }}>🎁 Ете ҡыҙ — Seven Girls</h2>
            </div>
            <div style={{ padding: '16px' }}>
              <p style={{ color: colors.white, fontSize: '14px', textAlign: 'center' }}>Seven sisters leaped from the cliff rather than be captured. The fountain in Ufa glows in their memory.</p>
              <button onClick={() => setShowTreasure(false)} style={{ width: '100%', marginTop: '16px', padding: '12px', backgroundColor: colors.honey, color: colors.darkBlue, border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
